void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 g = floor(fragCoord / 4.0);
  float t = mod(g.x + g.y, 2.0);
  fragColor = vec4(t, 1.0 - t, 0.5 + 0.5 * sin(iTime), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  fragColor = vec4(textureLod(iChannel0, uv, floor(uv.x * 6.0)).rgb, 1.0);
}
